package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	_ "github.com/shopspring/decimal"
)

// PartRec 01 PART-REC, 15 bytes
type PartRec struct { // 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                    // PIC X len=1
var WsLabel string = strings.Repeat(" ", 20)  // PIC X(20) len=20
var WsACount int64 = 0                        // PIC 99
var WsTotalA int64 = 0                        // PIC 999
var WsCount int64 = 0                         // PIC 999

// file handling
var partFile *os.File
var partReader *bufio.Reader
var curRec PartRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone(v bool) {
	if v {
		WsEofFlag = "Y"
	} else {
		WsEofFlag = "N"
	}
}

// helpers for numeric field truncation / formatting
func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}
func truncPIC(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	// COBOL keeps low-order digits; for positive values this is modulo
	// handle negative by truncating toward zero then keeping low order
	if v >= 0 {
		return v % mod
	}
	// negative: keep sign? But not needed for this program
	av := (-v) % mod
	return -av
}
func formatPIC9(v int64, digits int) string {
	tv := truncPIC(v, digits)
	if tv < 0 {
		tv = -tv
		// PIC 9 is unsigned in this program; negative not expected
	}
	return fmt.Sprintf("%0*d", digits, tv)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	if idx := strings.Index(s, " "); idx >= 0 {
		return s[:idx]
	}
	return s
}

// paragraph functions

func MainPara() {
	var err error
	partFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		if os.IsNotExist(err) {
			setInputDone(true)
			// still do summary
			SummaryPara()
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer partFile.Close()
	partReader = bufio.NewReader(partFile)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE already deferred, but mimic COBOL close before summary
	// need to keep file closed before summary (we already will)
	SummaryPara()
}

func ReadPara() {
	line, err := readLineSequential()
	if err != nil {
		if err == io.EOF {
			setInputDone(true)
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if line == nil {
		setInputDone(true)
		return
	}
	s := string(line)
	// pad with spaces on right if shorter than 15
	if len(s) < 15 {
		s = s + strings.Repeat(" ", 15-len(s))
	} else if len(s) > 15 {
		s = s[:15]
	}
	lbPart := s[0:8]
	lbRegion := s[8:11]
	lbSerialStr := s[11:15]

	var serial int64
	trim := strings.TrimSpace(lbSerialStr)
	if trim == "" {
		serial = 0
	} else {
		// DISPLAY numeric fields store digits only
		// parse as integer
		v, perr := strconv.ParseInt(trim, 10, 64)
		if perr != nil {
			// fallback: extract digits
			digits := ""
			for _, ch := range lbSerialStr {
				if ch >= '0' && ch <= '9' {
					digits += string(ch)
				}
			}
			if digits == "" {
				serial = 0
			} else {
				v2, _ := strconv.ParseInt(digits, 10, 64)
				serial = v2
			}
		} else {
			serial = v
		}
	}
	// truncate to 4 digits for storage (low-order)
	serial = truncPIC(serial, 4)

	curRec = PartRec{
		LbPart:   lbPart,
		LbRegion: lbRegion,
		LbSerial: serial,
	}
}

func readLineSequential() ([]byte, error) {
	if partReader == nil {
		return nil, io.EOF
	}
	// read until \n, handle CRLF and missing final newline
	b, err := partReader.ReadString('\n')
	if err != nil && err != io.EOF {
		return nil, err
	}
	if err == io.EOF && len(b) == 0 {
		return nil, io.EOF
	}
	// strip trailing \n and optional \r
	if len(b) > 0 && b[len(b)-1] == '\n' {
		b = b[:len(b)-1]
		if len(b) > 0 && b[len(b)-1] == '\r' {
			b = b[:len(b)-1]
		}
	}
	return []byte(b), nil
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := int64(strings.Count(curRec.LbPart, "A"))
	WsACount = truncPIC(cnt, 2)

	// STRING ... INTO WS-LABEL
	regionPart := delimitedBySpace(curRec.LbRegion)
	partPart := delimitedBySpace(curRec.LbPart)
	serialStr := formatPIC9(curRec.LbSerial, 4)
	body := regionPart + "-" + partPart + "-" + serialStr
	if len(body) > 20 {
		body = body[:20]
	} else if len(body) < 20 {
		body = body + strings.Repeat(" ", 20-len(body))
	}
	WsLabel = body

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = truncPIC(WsTotalA+WsACount, 3)
	// ADD 1 TO WS-COUNT
	WsCount = truncPIC(WsCount+1, 3)

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL X(20), " A=" literal, WS-A-COUNT PIC 99 zero-padded
	out := WsLabel + " A=" + formatPIC9(WsACount, 2)
	fmt.Println(out)

	ReadPara()
}

func SummaryPara() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A
	out := "LABELS: " + formatPIC9(WsCount, 3) + " A-TOTAL: " + formatPIC9(WsTotalA, 3)
	fmt.Println(out)
}

func main() {
	MainPara()
}
